clc;
clear;
close all;

% Given values
N1 = 6;
N2 = 0;

% Input sequences
x1 = [N1 N1/2 N1/4];
x2 = [N2/4 N2/2 N2];

% Convolution
y = conv(x1,x2);

% Display results
disp('x1[n] = '); %[output:77067873]
disp(x1); %[output:2b0cfb40]

disp('x2[n] = '); %[output:24db6ea9]
disp(x2); %[output:7531f89e]

disp('y[n] = x1[n] * x2[n] = '); %[output:0242d4be]
disp(y); %[output:5f6dd859]
n1 = 0:2;

figure; %[output:321c23d5]
stem(n1,x1,'filled'); %[output:321c23d5]
xlabel('n'); %[output:321c23d5]
ylabel('x_1[n]'); %[output:321c23d5]
title('x_1[n]'); %[output:321c23d5]
grid on; %[output:321c23d5]
figure; %[output:060482c4]
stem(n1,x2,'filled'); %[output:060482c4]
xlabel('n'); %[output:060482c4]
ylabel('x_2[n]'); %[output:060482c4]
title('x_2[n]'); %[output:060482c4]
grid on; %[output:060482c4]
n2 = 0:length(y)-1;

figure; %[output:951ccbc6]
stem(n2,y,'filled'); %[output:951ccbc6]
xlabel('n'); %[output:951ccbc6]
ylabel('y[n]'); %[output:951ccbc6]
title('Convolution y[n] = x_1[n] * x_2[n]'); %[output:951ccbc6]
grid on; %[output:951ccbc6]

